function validate([secret, words, allowedGuesses]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  if (words.some(word => typeof word !== 'string' || !/^[a-z]{6}$/.test(word))) return 'Every word is six lowercase letters.';
  if (new Set(words).size !== words.length) return 'The words must all be different.';
  if (!words.includes(secret)) return 'secret must be one of the words.';
  if (!Number.isInteger(allowedGuesses) || allowedGuesses < 10 || allowedGuesses > 30) return 'allowedGuesses is a whole number from 10 to 30.';
  return null;
}

