function adapt(input, solve, kit) {
  const [secret, words, allowedGuesses] = input;
  const known = new Set(words);
  let calls = 0;
  let found = false;
  // The secret stays inside this closure; the solution learns about it only through the scores.
  const master = Object.freeze({
    guess(word) {
      calls++;
      if (calls > allowedGuesses) throw new Error(`master.guess was called more than ${allowedGuesses} times; pick guesses that rule out more words.`);
      if (typeof word !== 'string' || !known.has(word)) return -1;
      if (word === secret) found = true;
      let count = 0;
      for (let i = 0; i < 6; i++) if (word[i] === secret[i]) count++;
      return count;
    },
  });
  solve(words, master);
  return found ? secret : 'The secret word was never guessed.';
}

