function findSecretWord(words, master) {
  function countMatches(a, b) {
    let count = 0;
    for (let i = 0; i < a.length; i++) {
      if (a[i] === b[i]) {
        count++;
      }
    }
    return count;
  }

  let candidates = words.slice();
  while (candidates.length > 0) {
    let guess = candidates[0];
    let bestWorst = Infinity;
    for (const word of candidates) {
      const groups = new Array(7).fill(0);
      for (const other of candidates) {
        groups[countMatches(word, other)]++;
      }
      const worst = Math.max(...groups);
      if (worst < bestWorst) {
        bestWorst = worst;
        guess = word;
      }
    }
    const result = master.guess(guess);
    if (result === 6) {
      return;
    }
    candidates = candidates.filter(word => countMatches(word, guess) === result);
  }
}

