function findSecretWord(words, master) {
  // Keep the words that fit every score so far, and guess the one that leaves the fewest words on average.
  const score = (a, b) => [...a].filter((letter, i) => letter === b[i]).length;
  let left = words;
  while (left.length) {
    let pick = 0, pickCost = Infinity;
    for (let i = 0; i < left.length; i++) {
      const sizes = new Map();
      for (const other of left) { const s = score(left[i], other); sizes.set(s, (sizes.get(s) || 0) + 1); }
      const cost = [...sizes.values()].reduce((sum, k) => sum + k * k, 0);
      if (cost < pickCost) { pickCost = cost; pick = i; }
    }
    const word = left[pick];
    const answer = master.guess(word);
    if (answer === 6) return;
    left = left.filter(other => score(other, word) === answer);
  }
}

