function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const same = (a, b) => { let s = 0; for (let i = 0; i < 6; i++) if (a[i] === b[i]) s++; return s; };
  // How the words in list split by the number of letters each shares with word.
  const groups = (word, list) => { const g = Array(7).fill(0); for (const other of list) g[same(word, other)]++; return g; };
  // The reference's rule (smallest largest group) and the brute force's rule (smallest sum of squared groups).
  const rules = [g => Math.max(...g), g => g.reduce((sum, k) => sum + k * k, 0)];
  // Plays one rule against the secret and reports whether it names the secret within the limit.
  const wins = (words, secret, limit, rule) => {
    let list = words;
    for (let turn = 1; turn <= limit; turn++) {
      let guess = list[0], best = Infinity;
      for (const word of list) { const cost = rule(groups(word, list)); if (cost < best) { best = cost; guess = word; } }
      if (guess === secret) return true;
      const score = same(guess, secret);
      list = list.filter(word => same(word, guess) === score);
    }
    return false;
  };
  for (;;) {
    // Each position draws from its own run of letters; a run of 1 fixes that letter, like a shared suffix.
    const runs = Array.from({ length: 6 }, () => (rand() < 0.2 ? 1 : 2 + pick(25)));
    const starts = runs.map(run => pick(27 - run));
    const n = size === 'large' ? 100 : 1 + pick(10);
    if (runs.reduce((product, run) => product * run, 1) < 2 * n) continue;
    const set = new Set();
    while (set.size < n) set.add(runs.map((run, i) => String.fromCharCode(97 + starts[i] + pick(run))).join(''));
    const words = [...set];
    const secret = words[pick(n)];
    const allowedGuesses = size === 'large' && rand() < 0.7 ? 10 : 10 + pick(21);
    // The problem promises that a sensible strategy succeeds, so keep only cases both strategies solve in time.
    if (rules.every(rule => wins(words, secret, allowedGuesses, rule))) return [secret, words, allowedGuesses];
  }
}
